SELECT c.relname,c.relrowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('vp_p19_analyses','vp_p19_reviews');
SELECT p.proname,p.prosecdef,has_function_privilege('anon',p.oid,'EXECUTE') anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') authenticated_execute FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'vp_p19_%' ORDER BY p.proname;
SELECT t,has_table_privilege('authenticated',t,'SELECT') can_read,has_table_privilege('authenticated',t,'INSERT') can_insert,has_table_privilege('authenticated',t,'UPDATE') can_update,has_table_privilege('authenticated',t,'DELETE') can_delete FROM unnest(ARRAY['public.vp_p19_analyses','public.vp_p19_reviews']) t;
